/**
 * A native join whose right operand is a GRAPH pushes the left bindings into the graph boundary as frame inputs
 * (Theorem C of the graph bind join ExecPlan), and keeps the independent evaluation when the policy rejects it.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeGraphBindJoinTest {

	private static final String NATIVE = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String EX = "http://example.com/";
	private static final int GRAPHS = 12;

	/** The target query of the ExecPlan; two of the twelve graphs are selected by VALUES ?g. */
	private static final String TARGET = "SELECT ?a ?g ?b ?c ?d { "
			+ "VALUES ?a { <http://example.com/test1> <http://example.com/test2> <http://example.com/test3> } "
			+ "VALUES ?g { <http://example.com/g1> <http://example.com/g2> } "
			+ "GRAPH ?g { ?b a <http://example.com/Type1> . ?a a ?t . "
			+ "OPTIONAL { ?a <http://example.com/p1> ?c } OPTIONAL { ?b <http://example.com/p2> ?d } } }";

	private static final Pattern FRAME_INPUTS = Pattern
			.compile("NativeGraph\\(selector=g, frameInputs=\\[([^\\]]*)\\]");

	@TempDir
	File directory;
	private SailRepository repository;

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void targetShapeBindJoinsLeftBindingsIntoTheGraph(boolean experimental) {
		open(experimental);

		// Hand-written oracle: g1 and g2 hold test1 and test2 (test1 also has p1); test3 occurs in no graph.
		List<String> expected = sorted(
				row("a", iri("test1"), "g", iri("g1"), "b", iri("b1"), "c", lit("c1"), "d", lit("d1")),
				row("a", iri("test2"), "g", iri("g1"), "b", iri("b1"), "d", lit("d1")),
				row("a", iri("test1"), "g", iri("g2"), "b", iri("b2"), "c", lit("c2"), "d", lit("d2")),
				row("a", iri("test2"), "g", iri("g2"), "b", iri("b2"), "d", lit("d2")));
		assertThat(rows(TARGET)).as("native result").containsExactlyElementsOf(expected);

		String telemetry = telemetry(TARGET);
		Matcher matcher = FRAME_INPUTS.matcher(telemetry);
		assertThat(matcher.find()).as(telemetry).isTrue();
		assertThat(Arrays.asList(matcher.group(1).split(",\\s*"))).as(telemetry).containsExactlyInAnyOrder("a", "g");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void graphsOutsideTheSiblingSelectionAreNotEvaluated(boolean experimental) {
		open(experimental);

		long before = NativeGraphPlan.BODY_PREPARATIONS.get();
		assertThat(rows(TARGET)).hasSize(4);
		long prepared = NativeGraphPlan.BODY_PREPARATIONS.get() - before;
		// Independent evaluation prepares the body once per named graph (12); the bind join once per (a, g) key that
		// reaches a selected graph (3 * 2 = 6), never for the ten unselected graphs.
		assertThat(prepared).as("graph body preparations").isPositive().isLessThan(GRAPHS);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void graphWrittenBeforeItsSiblingsIsStillBindJoinedAfterThem(boolean experimental) {
		open(experimental);
		String reordered = "SELECT ?a ?g ?b ?c ?d { "
				+ "GRAPH ?g { ?b a <http://example.com/Type1> . ?a a ?t . "
				+ "OPTIONAL { ?a <http://example.com/p1> ?c } OPTIONAL { ?b <http://example.com/p2> ?d } } "
				+ "VALUES ?g { <http://example.com/g1> <http://example.com/g2> } "
				+ "VALUES ?a { <http://example.com/test1> <http://example.com/test2> <http://example.com/test3> } }";

		assertThat(rows(reordered)).containsExactlyElementsOf(rows(TARGET)).hasSize(4);
		String telemetry = telemetry(reordered);
		Matcher matcher = FRAME_INPUTS.matcher(telemetry);
		assertThat(matcher.find()).as(telemetry).isTrue();
		assertThat(Arrays.asList(matcher.group(1).split(",\\s*"))).as(telemetry).containsExactlyInAnyOrder("a", "g");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void rejectedPolicyCasesKeepIndependentGraphEvaluation(boolean experimental) {
		open(experimental);
		String body = "GRAPH ?g { ?s ?p ?o OPTIONAL { ?s <http://example.com/p1> ?c } }";

		// no variable shared between the left operand and the graph
		assertNoFrameInputs("SELECT * { VALUES ?k { 1 2 } " + body + " }");

		// volatile body (not repeatable)
		assertNoFrameInputs("SELECT * { VALUES ?s { <http://example.com/test1> } GRAPH ?g { ?s ?p ?o "
				+ "OPTIONAL { ?s <http://example.com/p1> ?c } BIND(UUID() AS ?u) } }");

		// large left operand that does not bind the selector
		StringBuilder large = new StringBuilder("SELECT * { VALUES ?s {");
		for (int i = 0; i < 600; i++) {
			large.append(" <http://example.com/s").append(i).append('>');
		}
		large.append(" } ").append(body).append(" }");
		assertNoFrameInputs(large.toString());
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void siblingBoundDefaultGraphAliasSelectsItsPhysicalContextOnly(boolean experimental) {
		open(experimental);
		String query = "SELECT ?g ?s ?o { VALUES ?g { <" + RDF4J.NIL + "> } "
				+ "GRAPH ?g { ?s <http://example.com/p> ?o OPTIONAL { ?s <http://example.com/q> ?z } } }";

		// The alias is matched against the enumerated contexts, so only the physical rdf4j:nil context answers; the
		// default graph (holding default1) must not.
		assertThat(rows(query)).containsExactly(row("g", RDF4J.NIL, "o", iri("physicalObject"), "s",
				iri("physicalSubject")));
		Matcher matcher = FRAME_INPUTS.matcher(telemetry(query));
		assertThat(matcher.find()).isTrue();
		assertThat(matcher.group(1)).isEqualTo("g");
	}

	private void assertNoFrameInputs(String query) {
		String telemetry = telemetry(query);
		Matcher matcher = FRAME_INPUTS.matcher(telemetry);
		assertThat(matcher.find()).as(telemetry).isTrue();
		assertThat(matcher.group(1)).as(telemetry).isEmpty();
	}

	private IRI iri(String local) {
		return repository.getValueFactory().createIRI(EX + local);
	}

	private Value lit(String label) {
		return repository.getValueFactory().createLiteral(label);
	}

	private static String row(Object... nameValuePairs) {
		TreeMap<String, Value> sortedRow = new TreeMap<>();
		for (int i = 0; i < nameValuePairs.length; i += 2) {
			sortedRow.put((String) nameValuePairs[i], (Value) nameValuePairs[i + 1]);
		}
		return sortedRow.entrySet()
				.stream()
				.map(entry -> entry.getKey() + "=" + entry.getValue())
				.collect(Collectors.joining(";"));
	}

	private static List<String> sorted(String... rows) {
		return Arrays.stream(rows).sorted().toList();
	}

	private String telemetry(String query) {
		String previous = System.getProperty(NATIVE);
		System.setProperty(NATIVE, "true");
		try (var connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString();
		} finally {
			restore(previous);
		}
	}

	private List<String> rows(String query) {
		String previous = System.getProperty(NATIVE);
		System.setProperty(NATIVE, "true");
		try (var connection = repository.getConnection(); var result = connection.prepareTupleQuery(query).evaluate()) {
			List<String> rows = new ArrayList<>();
			while (result.hasNext()) {
				var row = result.next();
				rows.add(row.getBindingNames()
						.stream()
						.sorted()
						.map(name -> name + "=" + row.getValue(name))
						.collect(Collectors.joining(";")));
			}
			return rows.stream().sorted().toList();
		} finally {
			restore(previous);
		}
	}

	private static void restore(String previous) {
		if (previous == null) {
			System.clearProperty(NATIVE);
		} else {
			System.setProperty(NATIVE, previous);
		}
	}

	private void open(boolean experimental) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false));
		store.setExperimentalQueryOptimizations(experimental);
		repository = new SailRepository(store);
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		IRI type1 = vf.createIRI(EX + "Type1");
		try (var connection = repository.getConnection()) {
			for (int g = 1; g <= GRAPHS; g++) {
				IRI graph = vf.createIRI(EX + "g" + g);
				connection.add(vf.createIRI(EX + "b" + g), RDF.TYPE, type1, graph);
				connection.add(vf.createIRI(EX + "b" + g), vf.createIRI(EX + "p2"), vf.createLiteral("d" + g), graph);
				connection.add(vf.createIRI(EX + "test1"), RDF.TYPE, vf.createIRI(EX + "Class" + g), graph);
				connection.add(vf.createIRI(EX + "test2"), RDF.TYPE, vf.createIRI(EX + "Class" + g), graph);
				connection.add(vf.createIRI(EX + "test1"), vf.createIRI(EX + "p1"), vf.createLiteral("c" + g), graph);
				for (int k = 0; k < 20; k++) {
					connection.add(vf.createIRI(EX + "x" + g + "_" + k), RDF.TYPE, vf.createIRI(EX + "Filler"), graph);
				}
			}
			connection.add(vf.createIRI(EX + "default1"), vf.createIRI(EX + "p"), vf.createIRI(EX + "defaultObject"));
			connection.add(vf.createIRI(EX + "physicalSubject"), vf.createIRI(EX + "p"),
					vf.createIRI(EX + "physicalObject"), RDF4J.NIL);
		}
	}
}
